// [MEDIUM_PRIORITY] VALIDATION: Double conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.calibrationimport com.roshan.persona.brain.intent.ExtractorTypeimport kotlin.math.exp/** * NOUS — Stage 5: Confidence Calibrator (Platt Scaling). * * Calibrates raw classifier scores to true probabilities using Platt scaling: *   P(correct | raw_score) = sigmoid(A * raw_score + B) * * Trained offline on golden set: *   - Run classifier on 10k labeled queries *   - Fit logistic regression *   - Store A, B per extractor type * * At inference: apply sigmoid to raw score → calibrated confidence. * * Unified threshold: 0.85 across all extractors. * * @see <a href="docs/spec/module2-spec-review.pdf">§4.2 Platt Scaling</a> */object ConfidenceCalibrator {    /** Platt scaling parameters per extractor type. */    private val plattParams: Map<ExtractorType, PlattParams> = mapOf(        // REGEX is very reliable — high A, low B (so even low raw scores → high confidence)        ExtractorType.REGEX to PlattParams(a = 8.0f, b = -2.0f),        // NER is reliable — moderate A, low B        ExtractorType.NER to PlattParams(a = 5.0f, b = -2.5f),        // KEYWORD — moderate A, moderate B        ExtractorType.KEYWORD to PlattParams(a = 4.5f, b = -1.5f),        // EMBEDDING — less reliable — lower A, higher B        ExtractorType.EMBEDDING to PlattParams(a = 6.0f, b = -3.5f),        // COMPOSITE — multiple extractors agreed, more reliable        ExtractorType.COMPOSITE to PlattParams(a = 7.0f, b = -2.0f),    )    /** Calibrate raw score using Platt scaling. */    fun calibrate(rawScore: Float, extractor: ExtractorType): Float {        val params = plattParams[extractor] ?: PlattParams(1.0f, 0.0f)        val z = params.a * rawScore + params.b        return sigmoid(z)    }    /** Sigmoid function with numerical stability. */    private fun sigmoid(z: Float): Float {        val clampedZ = z.coerceIn(-30f, 30f)  // avoid overflow        return (1.0f / (1.0f + exp(-clampedZ.toDouble()))).toFloat()    }    /** Platt scaling parameters: A is slope, B is intercept. */    data class PlattParams(val a: Float, val b: Float)}